const response = $json.message?.content;

if (!response) {
  throw new Error("Ollama response is missing message.content");
}

let analysis;

try {
  analysis = JSON.parse(response);
} catch (error) {
  throw new Error("Ollama did not return valid JSON: " + error.message);
}

return {
  json: {
    is_relevant: Boolean(analysis.is_relevant),
    relevance_score: Number(analysis.relevance_score ?? 0),
    primary_topic: analysis.primary_topic ?? "Unknown",
    reason: analysis.reason ?? "",
    summary: analysis.summary ?? ""
  }
};

