function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function formatDate(value) {
  if (!value) return "Date inconnue";

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return escapeHtml(value);
  }

  return date.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "UTC"
  });
}

const today = new Date().toISOString().slice(0, 10);

const articlesHtml = papers.map((paper, index) => {
  const title = escapeHtml(paper.title || "Untitled paper");
  const url = /^https:\/\/arxiv\.org\/abs\/[\w.\/-]+$/.test(
    paper.url || ""
  ) ? paper.url : "";

  const linkHtml = url
    ? `<a href="${escapeHtml(url)}" style="color:#2563eb;text-decoration:none;">Read paper on arXiv â†’</a>`
    : `<span style="color:#64748b;">arXiv link unavailable</span>`;

  const authors = Array.isArray(paper.authors)
    ? paper.authors.join(", ")
    : (paper.authors || "Unknown");

  return `
    <div style="padding:22px 0;border-bottom:1px solid #e2e8f0;">
      <div style="font-size:12px;color:#64748b;margin-bottom:8px;">
        #${index + 1} &nbsp;|&nbsp; Published: ${formatDate(paper.published)}
        &nbsp;|&nbsp; AI relevance: ${escapeHtml(paper.llm_relevance_score)}/100
      </div>

      <h2 style="font-size:18px;line-height:1.4;margin:0 0 8px;color:#0f172a;">
        ${title}
      </h2>

      <p style="font-size:13px;color:#64748b;margin:0 0 12px;">
        ${escapeHtml(authors)}
      </p>

      <p style="font-size:14px;color:#334155;line-height:1.7;">
        ${escapeHtml(paper.summary || "No summary available.")}
      </p>

      <p style="font-size:13px;color:#475569;">
        <strong>Topic:</strong> ${escapeHtml(paper.primary_topic || "Not specified")}
      </p>

      <p style="font-size:13px;color:#475569;">
        <strong>Why it matters:</strong> ${escapeHtml(paper.reason || "No explanation available.")}
      </p>

      <p style="margin:16px 0 0;">${linkHtml}</p>
    </div>
  `;
}).join("");

const emptyMessage = `
  <p style="color:#475569;line-height:1.6;">
    No papers passed the relevance filters today. Try again in the next run.
  </p>
`;

